import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const port = 9339;
const url = process.argv[2];
const outPng = process.argv[3];

const prof = mkdtempSync(join(tmpdir(), 'bhchrome-'));
const ch = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
  '--remote-debugging-port=' + port, '--user-data-dir=' + prof,
  '--window-size=1200,800', '--disable-dev-shm-usage', url
], { stdio: ['ignore', 'pipe', 'pipe'] });

ch.stderr.on('data', () => {});
ch.stdout.on('data', () => {});

const delay = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  let ws;
  for (let i = 0; i < 60 && !ws; i++) {
    try {
      const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
      const page = list.find((t) => t.type === 'page');
      if (page) ws = new WebSocket(page.webSocketDebuggerUrl);
    } catch (e) {}
    if (!ws) await delay(250);
  }
  if (!ws) { console.error('CDP: no page target'); process.exit(2); }

  let id = 0;
  const pending = new Map();
  const events = [];
  ws.onmessage = (m) => {
    const msg = JSON.parse(m.data);
    if (msg.id != null && pending.has(msg.id)) { pending.get(msg.id).resolve(msg); pending.delete(msg.id); }
    else events.push(msg);
  };
  await new Promise((r) => { if (ws.readyState === 1) r(); else ws.onopen = r; });

  function send(method, params) {
    return new Promise((resolve) => {
      const i = ++id;
      pending.set(i, { resolve });
      ws.send(JSON.stringify({ id: i, method, params: params || {} }));
    });
  }

  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');

  await delay(7000);

  const shot = await send('Page.captureScreenshot', { format: 'png' });
  if (!shot.result || !shot.result.data) { console.error('screenshot failed'); process.exit(4); }
  const fs = await import('node:fs');
  fs.writeFileSync(outPng, Buffer.from(shot.result.data, 'base64'));

  const errs = events.filter((e) => {
    if (e.method === 'Runtime.exceptionThrown') return true;
    if (e.method === 'Runtime.consoleAPICalled' && (e.params.type === 'error')) return true;
    if (e.method === 'Log.entryAdded' && ['error'].includes(e.params.entry.level)) return true;
    return false;
  });

  let text = '';
  for (const e of errs) text += JSON.stringify(e.params) + '\n';
  console.log(text ? text : 'NO_PAGE_ERRORS');
  ws.close();
  ch.kill();
  process.exit(text ? 1 : 0);
}

main().catch((e) => { console.error(e); ch.kill(); process.exit(3); });
